reset role;
create temporary table trainer_workspaces(id uuid,owner_user_id uuid);
insert into pg_temp.trainer_workspaces values('42000000-0000-4000-8000-000000000001','41000000-0000-4000-8000-000000000002');
set local search_path = pg_temp, public, extensions;
set local role authenticated;
